local function Busy(api)
    local cast,channel=Casting(api,api.UnitCastingInfo),Casting(api,api.UnitChannelInfo)
    if cast==true or channel==true then return true end
    if cast==false and channel==false then return false end
end--[[APR_DIAG]]; Busy = APRTrace("APR-Core/features/navigation/NavigationV2Personal.lua:55:Busy#9", Busy)--[[/APR_DIAG]]

local function Ready(start,duration,enabled,rate)
    start,duration,rate=Number(start),Number(duration),Number(rate)
    if enabled~=true or not start or not duration or not rate or rate==0 then return nil end
    -- modRate describes UI playback. Non-unit rates are not extrapolated here.
    if rate~=1 then return nil end
    return Number(start+duration)
end--[[APR_DIAG]]; Ready = APRTrace("APR-Core/features/navigation/NavigationV2Personal.lua:61:Ready#10", Ready)--[[/APR_DIAG]]

local function Spell(api,d)
    local spells,book=api.C_Spell or {},api.C_SpellBook or {}
    local info=Call(api,spells.GetSpellInfo,d.spellID)
    local name=Field(api,info,'name')
    local loaded
    if type(name)=='string' and name~='' then loaded=true end
    local cooldown=Call(api,spells.GetSpellCooldown,d.spellID)
    local s={known=Boolean(Call(api,book.IsSpellKnown,d.spellID)),loaded=loaded,
        usable=Boolean(Call(api,spells.IsSpellUsable,d.spellID)),
        readyAt=Ready(Field(api,cooldown,'startTime'),Field(api,cooldown,'duration'),
            Field(api,cooldown,'isEnabled'),Field(api,cooldown,'modRate'))}
    local cast=Number(Field(api,info,'castTime'))
    if cast then s.castSeconds=cast/1000 end
    if d.chargeBased then
        local charges=Call(api,spells.GetSpellCharges,d.spellID)
        s.charges=Count(Field(api,charges,'currentCharges'))
        s.maxCharges=Count(Field(api,charges,'maxCharges'))
        s.rechargeStart=Number(Field(api,charges,'cooldownStartTime'))
        s.rechargeSeconds=Number(Field(api,charges,'cooldownDuration'))
        s.rechargeRate=Number(Field(api,charges,'chargeModRate'))
    end
    return s
end--[[APR_DIAG]]; Spell = APRTrace("APR-Core/features/navigation/NavigationV2Personal.lua:69:Spell#11", Spell)--[[/APR_DIAG]]

local function Item(api,d,count)
    local items=api.C_Item or {}
    local loaded=Boolean(Call(api,items.IsItemDataCachedByID,d.itemID))
    local start,duration,enabled=Call(api,items.GetItemCooldown,d.itemID)
    local owned
    if count then owned=count>0 end
    -- Uncached data is unknown, not a declaration that the item cannot exist.
    if loaded~=true then loaded=nil end
    return {owned=owned,loaded=loaded,usable=Boolean(Call(api,items.IsUsableItem,d.itemID)),
        readyAt=Ready(start,duration,enabled,1)}
end--[[APR_DIAG]]; Item = APRTrace("APR-Core/features/navigation/NavigationV2Personal.lua:93:Item#12", Item)--[[/APR_DIAG]]

function Adapter.Observe(api,declarations,settings,origin,loading)
    api,settings=api or _G,settings or {}
    local o={loading=Boolean(loading),allowRare=settings.allowRare==true,origin={},actions={},items={}}
    if o.loading~=false then return o end
    if type(origin)=='table' then
        for _,key in ipairs({'node','space','phase','reliable','indoors'}) do o.origin[key]=Public(api,origin[key]) end
    end
    o.observedAt=Number(Call(api,api.GetTime))
    o.moneyCopper=Count(Call(api,api.GetMoney))
    o.combat=Boolean(Call(api,api.InCombatLockdown))
    o.casting=Busy(api)
    o.origin.indoors=Boolean(Call(api,api.IsIndoors))
    local inventoried={}
    local function Inventory(id)
        if not inventoried[id] then
            inventoried[id]=true
            o.items[id]=Count(Call(api,(api.C_Item or {}).GetItemCount,id,false,false,false,false))
        end
        return o.items[id]
    end--[[APR_DIAG]]; Inventory = APRTrace("APR-Core/features/navigation/NavigationV2Personal.lua:118:Inventory#14", Inventory)--[[/APR_DIAG]]
    for index,d in ipairs(declarations or {}) do
        if index>256 then break end
        local s
        if d.kind=='spell' then s=Spell(api,d) else s=Item(api,d,Inventory(d.itemID)) end
        o.actions[d.id]=s
        for _,reagent in pairs(d.reagents or {}) do
            Inventory(reagent.itemID)
        end
    end
    return o
end--[[APR_DIAG]]; Adapter.Observe = APRTrace("APR-Core/features/navigation/NavigationV2Personal.lua:105:Adapter.Observe#13", Adapter.Observe)--[[/APR_DIAG]]

function Adapter.Same(a,b)
    if type(a)~='table' or type(b)~='table' then return false end
    if (a.observedAt==nil)~=(b.observedAt==nil) then return false end
    for _,key in ipairs({'combat','casting','loading','moneyCopper','allowRare','origin','actions','items'}) do
        if not Target.Same(a[key],b[key]) then return false end
    end
    for id,state in pairs(a.actions or {}) do
        local ready=state.readyAt
        if ready and a.observedAt and b.observedAt
            and (ready<=a.observedAt)~=(ready<=b.observedAt) then return false end
    end
    return true
end--[[APR_DIAG]]; Adapter.Same = APRTrace("APR-Core/features/navigation/NavigationV2Personal.lua:137:Adapter.Same#15", Adapter.Same)--[[/APR_DIAG]]

function Adapter.Label(action,api)
    api=api or _G
    return Target.Text(action and action.title,Target.Text(api.USE))
end--[[APR_DIAG]]; Adapter.Label = APRTrace("APR-Core/features/navigation/NavigationV2Personal.lua:151:Adapter.Label#16", Adapter.Label)--[[/APR_DIAG]]

local DISARM=[[
    self:SetAttribute("type", nil)
    self:SetAttribute("spell", nil)
    self:SetAttribute("item", nil)
    self:Hide()
]]

-- Install once outside combat. Secure snippets are static, never constructed
-- from action names, user text or data. Clear state never restores an old action.
function Adapter.CreateButton(api,parent)
    api=api or _G
    if Boolean(Call(api,api.InCombatLockdown))~=false then return nil,'combat_lockdown' end
    if type(api.CreateFrame)~='function' or type(api.RegisterStateDriver)~='function'
        or type(api.SecureHandlerWrapScript)~='function' then return nil,'secure_personal_unavailable' end
    local button=api.CreateFrame('Button',nil,parent or api.UIParent,
        'SecureActionButtonTemplate,SecureHandlerStateTemplate')
    button:Hide()
    button:RegisterForClicks('AnyUp','AnyDown')
    button:SetAttribute('_onstate-personalcombat','if newstate == "blocked" then '..DISARM..' end')
    api.SecureHandlerWrapScript(button,'OnClick',button,
        'if SecureCmdOptionParse("[combat] blocked; clear") == "blocked" then '..DISARM..' return false end')
    api.RegisterStateDriver(button,'personalcombat','[combat] blocked; clear')
    return button
end--[[APR_DIAG]]; Adapter.CreateButton = APRTrace("APR-Core/features/navigation/NavigationV2Personal.lua:165:Adapter.CreateButton#17", Adapter.CreateButton)--[[/APR_DIAG]]

-- The host owns the template and lifetime. Hardware clicks run Blizzard's
-- protected handler; this function only configures/disarms outside combat.
function Adapter.PrepareButton(button,action,api)
    api=api or _G
    if Boolean(Call(api,api.InCombatLockdown))~=false then return false,'combat_lockdown' end
    if type(button)~='table' or type(button.SetAttribute)~='function' then return nil,'invalid_personal_button' end
    button:SetAttribute('type',nil)
    button:SetAttribute('spell',nil)
    button:SetAttribute('item',nil)
    if type(button.Hide)=='function' then button:Hide() end
    if action==nil then return true end
    if action.status~='running' or action.phase~='ready' then return nil,'personal_not_ready' end
    local key=action.kind=='spell' and 'spellID' or action.kind=='item' and 'itemID'
    local id=key and Count(action[key])
    if not id or id==0 then return nil,'invalid_personal_action' end
    if action.kind=='spell' then button:SetAttribute('spell',id)
    else button:SetAttribute('item','item:'..id) end
    button:SetAttribute('type',action.kind)
    if type(button.Show)=='function' then button:Show() end
    return true
end--[[APR_DIAG]]; Adapter.PrepareButton = APRTrace("APR-Core/features/navigation/NavigationV2Personal.lua:183:Adapter.PrepareButton#18", Adapter.PrepareButton)--[[/APR_DIAG]]

ns.NavigationV2PersonalAdapter=Adapter
APR.NavigationV2Personal=Adapter
return Adapter
